import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Telemetry and Ceph-MGR for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"Telemetry and Ceph-MGR for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["Ceph","监控","性能优化","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Telemetry_and_Ceph-MGR_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/Telemetry_and_Ceph-MGR_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),l={name:"posts/2026/Telemetry_and_Ceph-MGR_for_Ceph_Developer_Summit_-_Vampire.md"};function i(n,e,d,h,s,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ceph-developer-summit-vampire-—-telemetry-与-ceph-mgr-专题会议纪要" tabindex="-1">Ceph Developer Summit (Vampire) — Telemetry 与 Ceph-MGR 专题会议纪要 <a class="header-anchor" href="#ceph-developer-summit-vampire-—-telemetry-与-ceph-mgr-专题会议纪要" aria-label="Permalink to &quot;Ceph Developer Summit (Vampire) — Telemetry 与 Ceph-MGR 专题会议纪要&quot;">​</a></h1><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次会议是 Ceph Developer Summit Vampire 版本的专题讨论，涵盖两大主题：<strong>Telemetry（遥测）</strong> 功能扩展计划，以及 <strong>Ceph-MGR（ceph-manager）</strong> 的痛点梳理与改进方向。</p><h2 id="一、telemetry-功能扩展计划" tabindex="-1">一、Telemetry 功能扩展计划 <a class="header-anchor" href="#一、telemetry-功能扩展计划" aria-label="Permalink to &quot;一、Telemetry 功能扩展计划&quot;">​</a></h2><p>发言人介绍了 Vampire 版本中 Telemetry 模块计划新增的三项内容：</p><h3 id="_1-dashboard-指标采集" tabindex="-1">1. Dashboard 指标采集 <a class="header-anchor" href="#_1-dashboard-指标采集" aria-label="Permalink to &quot;1. Dashboard 指标采集&quot;">​</a></h3><p>Dashboard 团队正在积极推进新指标的暴露工作。计划在 Vampire 版本中新增一个专门的 dashboard collection，将 Dashboard 侧即将暴露的所有新指标纳入 Telemetry 上报范围。</p><h3 id="_2-bluestore-默认-allocator-指标" tabindex="-1">2. BlueStore 默认 allocator 指标 <a class="header-anchor" href="#_2-bluestore-默认-allocator-指标" aria-label="Permalink to &quot;2. BlueStore 默认 allocator 指标&quot;">​</a></h3><p>目前 Ceph-MGR 无法方便地访问 BlueStore 默认 allocator 的相关指标，Vampire 版本中需要额外开发工作来将这些指标暴露给 manager，进而纳入 Telemetry 上报。</p><h3 id="_3-monitor-db-大小" tabindex="-1">3. Monitor DB 大小 <a class="header-anchor" href="#_3-monitor-db-大小" aria-label="Permalink to &quot;3. Monitor DB 大小&quot;">​</a></h3><p>计划在 Telemetry 报告中加入 MON 数据库（monitor DB）的大小信息，具体的采集方式仍需进一步设计确认。</p><h3 id="其他说明" tabindex="-1">其他说明 <a class="header-anchor" href="#其他说明" aria-label="Permalink to &quot;其他说明&quot;">​</a></h3><p>当前 Telemetry 服务正在向实验室（lab）迁移，近期出现了一些小问题，提醒社区成员关注相关进展。</p><h2 id="二、ceph-mgr-痛点梳理" tabindex="-1">二、Ceph-MGR 痛点梳理 <a class="header-anchor" href="#二、ceph-mgr-痛点梳理" aria-label="Permalink to &quot;二、Ceph-MGR 痛点梳理&quot;">​</a></h2><p>主持人 Nitin 介绍了当前已知的 Ceph-MGR 主要痛点，并邀请与会者补充。</p><h3 id="痛点一-健壮性与故障隔离-robustness-fault-isolation" tabindex="-1">痛点一：健壮性与故障隔离（Robustness &amp; Fault Isolation） <a class="header-anchor" href="#痛点一-健壮性与故障隔离-robustness-fault-isolation" aria-label="Permalink to &quot;痛点一：健壮性与故障隔离（Robustness &amp; Fault Isolation）&quot;">​</a></h3><p><strong>模块导致 manager 崩溃</strong>：当前模块之间缺乏有效的隔离机制，单个模块的异常（如 telemetry 模块的 assertion 错误）会导致整个 manager 进程崩溃。</p><p><strong>无 active manager（No Active Manager）</strong>：这是一个长期存在的 bug 集合，表现为：</p><ul><li>Manager 进程实际仍在运行，但集群状态显示 &quot;no active manager&quot;</li><li>根本原因包括：模块导致 manager 异常退出，或 beacon 心跳未被正确上报</li></ul><p><strong>内存泄漏（Memory Leaks）</strong>：</p><ul><li>无法定位是哪个模块导致了泄漏</li><li>近期案例：连接未正确关闭导致 OOM 杀死进程（已有相关 tracker，优先级 high）</li><li>历史案例：Rook 集成模块及 RESTful 模块（已下线）均曾引发内存泄漏</li></ul><h3 id="痛点二-可扩展性-scalability" tabindex="-1">痛点二：可扩展性（Scalability） <a class="header-anchor" href="#痛点二-可扩展性-scalability" aria-label="Permalink to &quot;痛点二：可扩展性（Scalability）&quot;">​</a></h3><p><strong>Manager hang</strong>：某些命令会导致整个 manager 挂起，而 manager 挂起往往发生在最需要它的时刻。</p><p><strong>Prometheus 端点超时</strong>：文档中已记录，1000 个 OSD 的集群中，缺乏缓存机制会导致 Prometheus 端点挂起，社区也有相关反馈案例。</p><p><strong>Python 3.12 迁移后的 pickle/unpickle 开销</strong>：升级到 Python 3.12 后，manager 在不必要的场景下仍执行 pickle/unpickle 操作，导致 CPU 和内存占用显著升高。</p><h3 id="痛点三-性能-performance" tabindex="-1">痛点三：性能（Performance） <a class="header-anchor" href="#痛点三-性能-performance" aria-label="Permalink to &quot;痛点三：性能（Performance）&quot;">​</a></h3><p><strong>消息限流（Throttling Messaging）</strong>：</p><ul><li>Manager 消息节流的默认大小（MS messenger）为 100 MB，在承载整个集群消息流量时明显不足</li><li>导致 manager hang 以及 PG 状态短暂变为 unknown</li><li>升级过程中也曾出现高 CPU 和 manager 无响应问题，相关 fix 已合并但缺乏测试手段</li></ul><p><strong><code>ok-to-upgrade</code> 命令的 bucket 类型支持</strong>（由 Radar 补充）：</p><ul><li>当前 <code>ok-to-upgrade</code> 命令仅支持 rack、chassis、host 和 OSD 这几种 bucket 类型</li><li>来自 field 的需求希望支持更高层级的 bucket 类型（如 data center、zone 等），这些 bucket 包含的 OSD 数量远多于 rack</li><li>核心瓶颈是 <code>check offline PGs</code> API 的性能，需要重新评估优化方案</li><li>目前已有对应 Jira（RFU race），后续会转为 tracker</li></ul><h3 id="痛点四-工程能力差距-engineering-gap" tabindex="-1">痛点四：工程能力差距（Engineering Gap） <a class="header-anchor" href="#痛点四-工程能力差距-engineering-gap" aria-label="Permalink to &quot;痛点四：工程能力差距（Engineering Gap）&quot;">​</a></h3><ul><li>大多数模块过去<strong>缺乏 unit tests</strong>，近期才开始补充</li><li>缺乏针对**模块故障拓扑（failure topology）**的测试</li><li><strong>内存泄漏检测</strong>的测试覆盖率不足，整体 Ceph-MGR 的测试体系有待完善</li></ul><h2 id="三、其他讨论" tabindex="-1">三、其他讨论 <a class="header-anchor" href="#三、其他讨论" aria-label="Permalink to &quot;三、其他讨论&quot;">​</a></h2><p><strong>Dashboard 过滤 API 请求</strong>：有人提及 Dashboard 侧曾有过滤 API 请求的需求，但随着 Umbrella 版本引入的 TTL cache manager 改进，这一问题可能已基本缓解。Umbrella 尚未 GA，待其正式发布后可以进一步评估效果。</p><p><strong>TTL Cache</strong> 被特别提及为一个长期期待且颇有价值的 enhancement，已在 Umbrella 中落地。</p><h2 id="四、后续行动" tabindex="-1">四、后续行动 <a class="header-anchor" href="#四、后续行动" aria-label="Permalink to &quot;四、后续行动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>负责方向</th><th>状态</th></tr></thead><tbody><tr><td>将 Dashboard 新指标加入 Telemetry collection</td><td>Dashboard + Telemetry 团队</td><td>计划中</td></tr><tr><td>暴露 BlueStore allocator 指标给 MGR</td><td>BlueStore/MGR 团队</td><td>待开发</td></tr><tr><td>设计 Monitor DB 大小的采集方案</td><td>MON/Telemetry 团队</td><td>待调研</td></tr><tr><td>MGR 模块故障隔离机制</td><td>MGR 团队</td><td>待立项</td></tr><tr><td>解决 no active manager 长期 bug</td><td>MGR 团队</td><td>持续跟进</td></tr><tr><td>内存泄漏定位与修复</td><td>MGR 团队</td><td>持续跟进</td></tr><tr><td>Prometheus 端点性能优化（缓存）</td><td>MGR/监控团队</td><td>待开发</td></tr><tr><td><code>ok-to-upgrade</code> 高层级 bucket 支持</td><td>MGR 团队</td><td>Jira 已创建</td></tr><tr><td>补充 MGR 模块 unit tests 与内存测试</td><td>各模块 owner</td><td>进行中</td></tr><tr><td>Telemetry 服务迁移至 lab</td><td>运维团队</td><td>进行中（有小问题）</td></tr></tbody></table><p>与会者可在 Etherpad 中补充其他痛点，并留下联系方式以便后续跟进。本次 summit 录像将于本周内上传至 Ceph 官方 YouTube 频道。</p>',38)])])}const u=t(l,[["render",i]]);export{c as __pageData,u as default};
